38	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
39	import org.springframework.samples.petclinic.rest.advice.OwnerCityAtCapacityException;
40	import org.springframework.samples.petclinic.rest.advice.OwnerDailyRegistrationLimitException;
41	import org.springframework.samples.petclinic.rest.api.OwnersApi;
42	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
43	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.PetDto;
45	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.samples.petclinic.util.AddressNormalizer;
50	import org.springframework.samples.petclinic.util.BusinessDayAdjuster;
51	import org.springframework.samples.petclinic.util.HouseholdNormalizer;
52	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
53	import org.springframework.security.access.prepost.PreAuthorize;
54	import org.springframework.web.bind.annotation.CrossOrigin;
55	import org.springframework.web.bind.annotation.RequestMapping;
56	import org.springframework.web.bind.annotation.RestController;
57	import org.springframework.web.util.UriComponentsBuilder;
58	
59	import jakarta.transaction.Transactional;
60	
61	/**
62	 * @author Vitaliy Fedoriv
63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    /**
71	     * Syntactic validation for an owner email: a non-empty local part, an '@', and a dotted domain
72	     * whose top-level label is at least two letters. Deliberately conservative so plainly malformed
73	     * input (e.g. a value without an '@') is rejected.
74	     */
75	    private static final Pattern EMAIL_PATTERN =
76	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
77	
78	    /**
79	     * Maximum number of owners a single city may hold. A create whose city already contains this many
80	     * owners is rejected with a {@code 409 Conflict} (see {@link #rejectCityAtCapacity}).
81	     */
82	    private static final int MAX_OWNERS_PER_CITY = 50;
83	
84	    /**
85	     * Maximum number of owners that may be registered in a single day. A create made once this many
86	     * owners already carry today's {@code registrationDate} is rejected with a {@code 429 Too Many
87	     * Requests} (see {@link #rejectDailyRegistrationLimitReached}).
88	     */
89	    private static final int MAX_OWNERS_PER_DAY = 100;
90	
91	    private final ClinicService clinicService;
92	
93	    private final OwnerMapper ownerMapper;
94	
95	    private final PetMapper petMapper;
96	
97	    private final VisitMapper visitMapper;
98	
99	    public OwnerRestControllerV1(ClinicService clinicService,
100	                                 OwnerMapper ownerMapper,
101	                                 PetMapper petMapper,
102	                                 VisitMapper visitMapper) {
103	        this.clinicService = clinicService;
104	        this.ownerMapper = ownerMapper;
105	        this.petMapper = petMapper;
106	        this.visitMapper = visitMapper;
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
112	        Collection<Owner> owners;
113	        if (lastName != null) {
114	            owners = this.clinicService.findOwnerByLastName(lastName);
115	        } else {
116	            owners = this.clinicService.findAllOwners();
117	        }
118	        if (owners.isEmpty()) {
119	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
120	        }
121	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
122	    }
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
127	        Owner owner = this.clinicService.findOwnerById(ownerId);
128	        if (owner == null) {
129	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
130	        }
131	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
137	        normalizeAddress(ownerFieldsDto);
138	        rejectBlankOwnerFields(ownerFieldsDto);
139	        normalizeTelephone(ownerFieldsDto);
140	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
141	        rejectDuplicateHousehold(ownerFieldsDto);
142	        rejectCityAtCapacity(ownerFieldsDto.getCity());
143	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate());
144	        rejectDailyRegistrationLimitReached(registrationDate);
145	        normalizeEmail(ownerFieldsDto);
146	        HttpHeaders headers = new HttpHeaders();
147	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
148	        owner.setRegistrationDate(registrationDate);
149	        owner.setHouseholdId(HouseholdNormalizer.toHouseholdId(owner.getLastName(), owner.getAddress()));
150	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
151	        this.clinicService.saveOwner(owner);
152	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
153	        headers.setLocation(UriComponentsBuilder.newInstance()
154	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
155	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Override
160	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
161	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
162	        if (currentOwner == null) {
163	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
164	        }
165	        currentOwner.setAddress(ownerFieldsDto.getAddress());
166	        currentOwner.setCity(ownerFieldsDto.getCity());
167	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
168	        currentOwner.setLastName(ownerFieldsDto.getLastName());
169	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
170	        normalizeEmail(ownerFieldsDto);
171	        currentOwner.setEmail(ownerFieldsDto.getEmail());
172	        currentOwner.setHouseholdId(
173	            HouseholdNormalizer.toHouseholdId(currentOwner.getLastName(), currentOwner.getAddress()));
174	        this.clinicService.saveOwner(currentOwner);
175	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Transactional
180	    @Override
181	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
182	        Owner owner = this.clinicService.findOwnerById(ownerId);
183	        if (owner == null) {
184	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
185	        }
186	        this.clinicService.deleteOwner(owner);
187	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
188	    }
189	
190	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
191	    @Override
192	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
193	        Owner owner = this.clinicService.findOwnerById(ownerId);
194	        if (owner == null) {
195	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
196	        }
197	        HttpHeaders headers = new HttpHeaders();
198	        Pet pet = petMapper.toPet(petFieldsDto);
199	        owner.setId(ownerId);
200	        pet.setOwner(owner);
201	        pet.getType().setName(null);
202	        this.clinicService.savePet(pet);
203	        PetDto petDto = petMapper.toPetDto(pet);
204	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
205	            .buildAndExpand(pet.getId()).toUri());
206	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
207	    }
208	
209	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
210	    @Override
211	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
212	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
213	        if (currentOwner != null) {
214	            Pet currentPet = this.clinicService.findPetById(petId);
215	            if (currentPet != null) {
216	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
217	                currentPet.setName(petFieldsDto.getName());
218	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
219	                this.clinicService.savePet(currentPet);
220	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
221	            }
222	        }
223	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
224	    }
225	
226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Override
228	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
229	        HttpHeaders headers = new HttpHeaders();
230	        Visit visit = visitMapper.toVisit(visitFieldsDto);
231	        Pet pet = new Pet();
232	        pet.setId(petId);
233	        visit.setPet(pet);
234	        this.clinicService.saveVisit(visit);
235	        VisitDto visitDto = visitMapper.toVisitDto(visit);
236	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
237	            .buildAndExpand(visit.getId()).toUri());
238	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
239	    }
240	
241	
242	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
243	    @Override
244	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
245	        Owner owner = this.clinicService.findOwnerById(ownerId);
246	        if (owner != null) {
247	            Pet pet = owner.getPet(petId);
248	            if (pet != null) {
249	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
250	            }
251	        }
252	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
253	    }
254	
255	    /**
256	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
257	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
258	     * the request body already rejects null and empty values, but permits whitespace-only strings
259	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
260	     * that gap so every required field must carry a non-blank value.
261	     *
262	     * @param ownerFieldsDto the submitted owner fields
263	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
264	     */
265	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
266	        List<String> missing = new ArrayList<>();
267	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
268	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
269	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
270	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
271	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
272	        if (!missing.isEmpty()) {
273	            throw new InvalidOwnerFieldsException(missing);
274	        }
275	    }
276	
277	    private void addIfBlank(List<String> missing, String fieldName, String value) {
278	        if (value == null || value.isBlank()) {
279	            missing.add(fieldName);
280	        }
281	    }
282	
283	    /**
284	     * Normalizes the submitted {@code address} on create to its canonical form (see
285	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
286	     * stored and returned, and the form every later address comparison (the required-field check,
287	     * household duplicate detection and the shared household id) is judged on. A null address is left
288	     * untouched so {@link #rejectBlankOwnerFields} still reports it as missing; a value that is blank
289	     * after normalization likewise reduces to the empty string and is rejected there.
290	     *
291	     * @param ownerFieldsDto the submitted owner fields
292	     */
293	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
294	        String address = ownerFieldsDto.getAddress();
295	        if (address == null) {
296	            return;
297	        }
298	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(address));
299	    }
300	
301	    /**
302	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
303	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
304	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
305	     * {@code 400 Bad Request}.
306	     *
307	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
308	     *                       {@link #rejectBlankOwnerFields} having already run)
309	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
310	     */
311	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
312	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
313	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
314	        ownerFieldsDto.setTelephone(normalized);
315	    }
316	
317	    /**
318	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
319	     * untouched (email is optional). When present it is trimmed and, after validating that it is a
320	     * syntactically valid address, written back lower-cased so it is the value stored and returned.
321	     * Any present-but-invalid address is rejected with a {@code 400 Bad Request}.
322	     *
323	     * @param ownerFieldsDto the submitted owner fields
324	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address
325	     */
326	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
327	        String email = ownerFieldsDto.getEmail();
328	        if (email == null || email.isBlank()) {
329	            return;
330	        }
331	        email = email.trim();
332	        if (!EMAIL_PATTERN.matcher(email).matches()) {
333	            throw new InvalidOwnerFieldsException(List.of("email"));
334	        }
335	        ownerFieldsDto.setEmail(email.toLowerCase(Locale.ROOT));
336	    }
337	
338	    /**
339	     * Rejects creating an owner whose normalized telephone is already used by any other owner.
340	     * Both the submitted telephone and every existing owner's stored telephone are reduced to their
341	     * {@linkplain TelephoneNormalizer#toComparisonKey comparison key} before comparison, so equality
342	     * is judged on that key alone. A match is reported as a {@code 409 Conflict}.
343	     *
344	     * @param normalizedTelephone the submitted telephone, already reduced to its canonical form by
345	     *                            {@link #normalizeTelephone}
346	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same telephone
347	     */
348	    private void rejectDuplicateTelephone(String normalizedTelephone) {
349	        String comparisonKey = TelephoneNormalizer.toComparisonKey(normalizedTelephone);
350	        boolean inUse = this.clinicService.findAllOwners().stream()
351	            .map(Owner::getTelephone)
352	            .filter(Objects::nonNull)
353	            .map(TelephoneNormalizer::toComparisonKey)
354	            .anyMatch(comparisonKey::equals);
355	        if (inUse) {
356	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
357	        }
358	    }
359	
360	    /**
361	     * Rejects creating an owner who shares a household with any existing owner, unless the request
362	     * opts in with {@code sharesHousehold} set to {@code true}. Two owners share a household when they
363	     * have the same {@code lastName} and {@code address}, compared case-insensitively and with runs of
364	     * whitespace collapsed (see {@link HouseholdNormalizer}); the submitted fields and every existing
365	     * owner's stored fields are reduced to their {@linkplain HouseholdNormalizer#toComparisonKey
366	     * comparison key} before comparison. A match is reported as a {@code 409 Conflict}.
367	     *
368	     * @param ownerFieldsDto the submitted owner fields (its {@code lastName} and {@code address} are
369	     *                       non-blank here, {@link #rejectBlankOwnerFields} having already run)
370	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household and the
371	     *                                          request did not opt in with {@code sharesHousehold}
372	     */
373	    /**
374	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
375	     * both match the submitted values, compared case-insensitively. The count reflects only owners
376	     * already persisted at the time of the create, so the owner being created is never included.
377	     *
378	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
379	     *                  having already run)
380	     * @param lastName  the submitted last name (non-blank here)
381	     * @return the number of existing owners sharing the same first and last name
382	     */
383	    private int countNamesakes(String firstName, String lastName) {
384	        return (int) this.clinicService.findAllOwners().stream()
385	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
386	                && lastName.equalsIgnoreCase(owner.getLastName()))
387	            .count();
388	    }
389	
390	    /**
391	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
392	     * The submitted city is compared case-insensitively against every existing owner's stored city; a
393	     * city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
394	     *
395	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
396	     *             run)
397	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
398	     */
399	    private void rejectCityAtCapacity(String city) {
400	        long ownersInCity = this.clinicService.findAllOwners().stream()
401	            .map(Owner::getCity)
402	            .filter(Objects::nonNull)
403	            .filter(city::equalsIgnoreCase)
404	            .count();
405	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
406	            throw new OwnerCityAtCapacityException(city);
407	        }
408	    }
409	
410	    /**
411	     * Resolves the effective registration date for a create, rolled onto a business day. The
412	     * supplied date is used when present, otherwise the server's current date; either way the result
413	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
414	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
415	     * stored {@code registrationDate}, the membership number's year segment and the daily
416	     * create-limit's per-day count - is judged on this adjusted date.
417	     *
418	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
419	     *                                 default to the server's current date
420	     * @return the effective registration date, guaranteed to fall on a business day
421	     */
422	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
423	        LocalDate registrationDate =
424	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
425	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
426	    }
427	
428	    /**
429	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
430	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
431	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
432	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
433	     * Too Many Requests}.
434	     *
435	     * @param registrationDate the create's effective registration date, already rolled onto a business
436	     *                         day by {@link #effectiveRegistrationDate}
437	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
438	     *                                              owner registrations
439	     */
440	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate) {
441	        long registeredThatDay = this.clinicService.findAllOwners().stream()
442	            .map(Owner::getRegistrationDate)
443	            .filter(registrationDate::equals)
444	            .count();
445	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
446	            throw new OwnerDailyRegistrationLimitException(registrationDate);
447	        }
448	    }
449	
450	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
451	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
452	            return;
453	        }
454	        String comparisonKey = HouseholdNormalizer.toComparisonKey(
455	            ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
456	        boolean inUse = this.clinicService.findAllOwners().stream()
457	            .filter(owner -> owner.getLastName() != null && owner.getAddress() != null)
458	            .map(owner -> HouseholdNormalizer.toComparisonKey(owner.getLastName(), owner.getAddress()))
459	            .anyMatch(comparisonKey::equals);
460	        if (inUse) {
461	            throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
462	        }
463	    }
464	}
